def transform(grid):
    left = [row[:4] for row in grid]
    right = [row[5:9] for row in grid]
    if any(left[r][c] and right[r][c] for r in range(4) for c in range(4)):
        return left
    return [[right[r][c] if right[r][c] else left[r][c] for c in range(4)] for r in range(4)]
